// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address target, uint256 value, bytes calldata data, address nonOwner) public {
        vm.assume(nonOwner != c.owner());
        vm.deal(address(c), value);
        vm.prank(nonOwner);
        bool ok;
        try c.sendMoney(target, value, data) { ok = true; } catch { ok = false; }
        assertTrue(!ok);
    }
}
